procedure:public.enqueue_due_deliveries(.source_code:
declare
  due_record record;
  created_delivery_id uuid;
  next_at timestamptz;
  normal_window_start timestamptz;
  last_sent_at timestamptz;
  window_start timestamptz;
begin
  for due_record in
    select subscriber.id as subscriber_id,
           preference.version as preference_version,
           preference.language,
           preference.theme,
           schedule.next_delivery_at,
           schedule.frequency,
           schedule.weekly_day,
           schedule.local_delivery_time,
           schedule.timezone
    from public.subscribers as subscriber
    join public.subscriber_preferences as preference on preference.subscriber_id = subscriber.id
    join public.subscriber_schedules as schedule on schedule.subscriber_id = subscriber.id
    where subscriber.status = 'active'
      and subscriber.verified_at is not null
      and schedule.next_delivery_at is not null
      and schedule.next_delivery_at <= p_now
    order by schedule.next_delivery_at, subscriber.id
    for update of subscriber, preference, schedule skip locked
    limit greatest(1, least(p_batch_size, 200))
  loop
    begin
      created_delivery_id := null;
      last_sent_at := null;
      next_at := public.compute_next_delivery_at(
        due_record.next_delivery_at,
        due_record.frequency,
        due_record.weekly_day,
        due_record.local_delivery_time,
        due_record.timezone
      );
      normal_window_start := public.compute_delivery_window_start(
        due_record.next_delivery_at,
        due_record.frequency,
        due_record.weekly_day,
        due_record.local_delivery_time,
        due_record.timezone
      );
      select max(prior.scheduled_for)
      into last_sent_at
      from public.deliveries as prior
      where prior.subscriber_id = due_record.subscriber_id
        and prior.status = 'sent'
        and prior.scheduled_for < due_record.next_delivery_at;
      window_start := greatest(coalesce(last_sent_at, normal_window_start), normal_window_start);

      insert into public.deliveries (
        subscriber_id, scheduled_for, preference_version, language, theme,
        next_attempt_at, news_window_started_at, news_window_ended_at,
        next_personalization_at
      ) values (
        due_record.subscriber_id, due_record.next_delivery_at,
        due_record.preference_version, due_record.language, due_record.theme,
        p_now, window_start, due_record.next_delivery_at, p_now
      )
      on conflict on constraint deliveries_subscriber_scheduled_for_key do nothing
      returning id into created_delivery_id;

      update public.subscriber_schedules
      set last_scheduled_at = due_record.next_delivery_at,
          next_delivery_at = next_at,
          schedule_error_code = null,
          schedule_error_at = null
      where public.subscriber_schedules.subscriber_id = due_record.subscriber_id;

      if created_delivery_id is not null then
        delivery_id := created_delivery_id;
        subscriber_id := due_record.subscriber_id;
        scheduled_for := due_record.next_delivery_at;
        return next;
      end if;
    exception when others then
      update public.subscriber_schedules
      set next_delivery_at = null,
          schedule_error_code = 'invalid-schedule-data',
          schedule_error_at = p_now
      where public.subscriber_schedules.subscriber_id = due_record.subscriber_id;
    end;
  end loop;
end;

procedure:public.fail_delivery_personali.source_code:
begin
  if not p_is_permanent and (p_retry_at is null or p_retry_at <= p_now) then
    raise exception using errcode = '22023', message = 'future retry time required';
  end if;
  update public.deliveries
  set personalization_status = case
        when p_is_permanent then 'failed'::public.personalization_status
        else 'retry-wait'::public.personalization_status
      end,
      next_personalization_at = case
        when p_is_permanent then next_personalization_at else p_retry_at
      end,
      personalization_failure_code = left(coalesce(p_failure_code, 'personalization-failed'), 100),
      personalization_lease_token = null,
      personalization_lease_owner = null,
      personalization_lease_expires_at = null
  where id = p_delivery_id
    and personalization_lease_token = p_lease_token
    and personalization_status = 'selecting';
  return found;
end;

procedure:public.finish_article_claim(uu.source_code:
begin
  if p_status not in ('processed', 'retry-wait', 'failed', 'quarantined') then
    raise exception using errcode = '22023', message = 'invalid terminal article claim status';
  end if;
  if p_status = 'retry-wait' and (p_retry_at is null or p_retry_at <= p_now) then
    raise exception using errcode = '22023', message = 'future retry time required';
  end if;

  update public.articles
  set processing_status = p_status,
      next_processing_at = coalesce(p_retry_at, next_processing_at),
      last_error_code = p_error_code,
      processed_at = case when p_status = 'processed' then p_now else processed_at end,
      lease_token = null,
      lease_owner = null,
      lease_expires_at = null
  where id = p_article_id and lease_token = p_lease_token and processing_status = 'claimed';
  return found;
end;

procedure:public.insert_ingested_article.source_code:
declare
  inserted_id uuid;
  duplicate_record public.articles%rowtype;
begin
  perform 1
  from public.sources
  where id = p_source_id
    and lease_token = p_source_lease_token
    and is_active
    and terms_status = 'approved'
    and technical_status = 'verified';
  if not found then
    raise exception using errcode = '55000', message = 'active source lease required';
  end if;

  if p_duplicate_of_article_id is not null then
    select * into duplicate_record
    from public.articles
    where id = p_duplicate_of_article_id;

    if not found or duplicate_record.source_id <> p_source_id then
      raise exception using errcode = '22023', message = 'duplicate target must use the same source';
    end if;
    if p_duplicate_kind = 'same-source-title'
       and abs(extract(epoch from (p_published_at - duplicate_record.published_at))) > 259200 then
      raise exception using errcode = '22023', message = 'title duplicate is outside the 72-hour bound';
    elsif p_duplicate_kind = 'same-source-near-title'
       and abs(extract(epoch from (p_published_at - duplicate_record.published_at))) > 21600 then
      raise exception using errcode = '22023', message = 'near duplicate is outside the 6-hour bound';
    elsif p_duplicate_kind not in ('same-source-title', 'same-source-near-title') then
      raise exception using errcode = '22023', message = 'invalid duplicate kind';
    end if;
  elsif p_duplicate_kind is not null then
    raise exception using errcode = '22023', message = 'duplicate kind requires a target';
  end if;

  insert into public.articles (
    source_id, original_title, normalized_title, original_url, canonical_url,
    canonical_url_hash, normalized_title_hash, description, author, published_at,
    declared_language, country_code, state_region, city, feed_categories,
    raw_metadata, feed_entry_id, feed_updated_at, timestamp_source,
    language_source, geography_source, duplicate_of_article_id, duplicate_kind,
    normalization_version, processing_status, next_processing_at
  ) values (
    p_source_id, p_original_title, p_normalized_title, p_original_url, p_canonical_url,
    p_canonical_url_hash, p_normalized_title_hash, p_description, p_author, p_published_at,
    p_declared_language, p_country_code, p_state_region, p_city,
    coalesce(p_feed_categories, '{}'), p_raw_metadata, p_feed_entry_id,
    p_feed_updated_at, p_timestamp_source, p_language_source, p_geography_source,
    p_duplicate_of_article_id, p_duplicate_kind, p_normalization_version,
    case
      when p_duplicate_of_article_id is null then 'pending'::public.article_processing_status
      else 'quarantined'::public.article_processing_status
    end,
    p_now
  )
  on conflict (canonical_url_hash) do nothing
  returning id into inserted_id;

  if inserted_id is null then
    return query select null::uuid, 'exact-duplicate'::text;
  elsif p_duplicate_of_article_id is not null then
    return query select inserted_id, 'near-duplicate'::text;
  else
    return query select inserted_id, 'inserted'::text;
  end if;
end;

procedure:public.insert_ingested_article.definition:
CREATE OR REPLACE FUNCTION public.insert_ingested_article(p_source_id uuid, p_source_lease_token uuid, p_original_title text, p_normalized_title text, p_original_url text, p_canonical_url text, p_canonical_url_hash bytea, p_normalized_title_hash bytea, p_description text, p_author text, p_published_at timestamp with time zone, p_declared_language public.briefing_language, p_country_code text, p_state_region text, p_city text, p_feed_categories text[], p_raw_metadata jsonb, p_feed_entry_id text DEFAULT NULL::text, p_feed_updated_at timestamp with time zone DEFAULT NULL::timestamp with time zone, p_timestamp_source text DEFAULT NULL::text, p_language_source text DEFAULT NULL::text, p_geography_source text DEFAULT NULL::text, p_duplicate_of_article_id uuid DEFAULT NULL::uuid, p_duplicate_kind text DEFAULT NULL::text, p_normalization_version text DEFAULT 'phase-6-v1'::text, p_now timestamp with time zone DEFAULT statement_timestamp())
 RETURNS TABLE(article_id uuid, outcome text)
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
declare
  inserted_id uuid;
  duplicate_record public.articles%rowtype;
begin
  perform 1
  from public.sources
  where id = p_source_id
    and lease_token = p_source_lease_token
    and is_active
    and terms_status = 'approved'
    and technical_status = 'verified';
  if not found then
    raise exception using errcode = '55000', message = 'active source lease required';
  end if;

  if p_duplicate_of_article_id is not null then
    select * into duplicate_record
    from public.articles
    where id = p_duplicate_of_article_id;

    if not found or duplicate_record.source_id <> p_source_id then
      raise exception using errcode = '22023', message = 'duplicate target must use the same source';
    end if;
    if p_duplicate_kind = 'same-source-title'
       and abs(extract(epoch from (p_published_at - duplicate_record.published_at))) > 259200 then
      raise exception using errcode = '22023', message = 'title duplicate is outside the 72-hour bound';
    elsif p_duplicate_kind = 'same-source-near-title'
       and abs(extract(epoch from (p_published_at - duplicate_record.published_at))) > 21600 then
      raise exception using errcode = '22023', message = 'near duplicate is outside the 6-hour bound';
    elsif p_duplicate_kind not in ('same-source-title', 'same-source-near-title') then
      raise exception using errcode = '22023', message = 'invalid duplicate kind';
    end if;
  elsif p_duplicate_kind is not null then
    raise exception using errcode = '22023', message = 'duplicate kind requires a target';
  end if;

  insert into public.articles (
    source_id, original_title, normalized_title, original_url, canonical_url,
    canonical_url_hash, normalized_title_hash, description, author, published_at,
    declared_language, country_code, state_region, city, feed_categories,
    raw_metadata, feed_entry_id, feed_updated_at, timestamp_source,
    language_source, geography_source, duplicate_of_article_id, duplicate_kind,
    normalization_version, processing_status, next_processing_at
  ) values (
    p_source_id, p_original_title, p_normalized_title, p_original_url, p_canonical_url,
    p_canonical_url_hash, p_normalized_title_hash, p_description, p_author, p_published_at,
    p_declared_language, p_country_code, p_state_region, p_city,
    coalesce(p_feed_categories, '{}'), p_raw_metadata, p_feed_entry_id,
    p_feed_updated_at, p_timestamp_source, p_language_source, p_geography_source,
    p_duplicate_of_article_id, p_duplicate_kind, p_normalization_version,
    case
      when p_duplicate_of_article_id is null then 'pending'::public.article_processing_status
      else 'quarantined'::public.article_processing_status
    end,
    p_now
  )
  on conflict (canonical_url_hash) do nothing
  returning id into inserted_id;

  if inserted_id is null then
    return query select null::uuid, 'exact-duplicate'::text;
  elsif p_duplicate_of_article_id is not null then
    return query select inserted_id, 'near-duplicate'::text;
  else
    return query select inserted_id, 'inserted'::text;
  end if;
end;
$function$

